#!/usr/bin/env python3
"""Generate the Unicode vectors that pin impl2's text handling to validate.py.

Three operations decide what a report says, and Go's standard library does none of
them the way Python does:

  str.strip()   strips U+001C..U+001F, which unicode.IsSpace does not.
  str.lower()   applies SpecialCasing (U+0130 expands to two runes) and the
                context-sensitive Final_Sigma rule, which strings.ToLower does
                not, and folds case pairs added after Python's Unicode version.
  repr()        escapes by Unicode category; see make_repr.py.

Final_Sigma needs the Cased and Case_Ignorable properties. Neither is exposed by
Python, so both are derived here from observable behaviour: a rune is Cased if
isupper/islower/Lt says so, and a non-Cased rune is Case_Ignorable exactly when
wedging it between a capital sigma and a capital alpha leaves the sigma non-final.

    python3 impl2/testdata/make_unicode.py
"""

import json
import os
import sys
import unicodedata

HERE = os.path.dirname(os.path.abspath(__file__))

PROBES = [
    "",
    "plain",
    "TRUE",
    "True",
    "ΟΔΟΣ",
    "ΟΔΟΣ Α",
    "ΟΣ",
    "ΣΣ",
    "ΑΣΑ",
    "Σ",
    "ς",
    "ΟΔΟΣ'",
    "ΑΣ'Α",
    "ΑΣ.Α",
    "ΑΣ Α",
    "ΑΣ\u00adΑ",
    "ΑΣ\u0301Α",
    "İ",
    "İstanbul",
    "ǅ",
    "ᾈ",
    "꟎꟏",
    "\U00016ea0\U00016ebb",
    "sha256:" + "A" * 64,
    "  padded  ",
    "\x1cpadded\x1f",
    "\u00a0padded\u2007",
    "ΣΣΣ",
    "Α Σ Β",
    "Σ\u2019Α",
]


def ranges(points):
    out = []
    for point in sorted(points):
        if out and point == out[-1][1] + 1:
            out[-1][1] = point
        else:
            out.append([point, point])
    return out


def lower_ranges(lower):
    """Compact single-rune mappings into runs of constant offset."""
    single, expansions = [], {}
    for key, value in lower.items():
        point = int(key, 16)
        parts = [int(x, 16) for x in value.split()]
        if len(parts) == 1:
            single.append((point, parts[0] - point))
        else:
            expansions[point] = parts
    spans = []
    for point, delta in sorted(single):
        if spans and spans[-1][1] == point - 1 and spans[-1][2] == delta:
            spans[-1][1] = point
        else:
            spans.append([point, point, delta])
    return spans, expansions


# The header names the minor version, not the patch. These tables are a
# function of the Unicode data shipped with the series; a patch release does
# not change it, and a stamp that moved with every patch would turn a
# toolchain upgrade into a failed pin for a reason that is not in the format.
# The data itself is pinned by the vectors, so nothing goes unchecked.
GO_HEADER = '''package main

// Code generated by testdata/make_unicode.py from Python %s (Unicode %s).
// DO NOT EDIT: regenerate with `python3 impl2/testdata/make_unicode.py`.
//
// These tables pin impl2's text handling to the reference implementation instead
// of to Go's Unicode version, which is newer. reference.go explains why each one
// is needed; reference_test.go checks every code point against the same data.
'''


def write_go(document, path):
    spans, expansions = lower_ranges(document["lower"])
    lines = [GO_HEADER % ("%d.%d" % (sys.version_info[0], sys.version_info[1]),
                          document["unicode_version"])]
    lines.append("// referenceWhitespace is str.isspace(), which includes U+001C..U+001F.")
    lines.append("var referenceWhitespace = []rune{")
    for point in document["whitespace"]:
        lines.append("\t0x%04X," % point)
    lines.append("}\n")
    for name, key, comment in (
        ("referenceCasedSpans", "cased", "referenceCasedSpans is the Unicode Cased property: Uppercase, Lowercase or Lt."),
        ("referenceCaseIgnorableSpans", "case_ignorable",
         "referenceCaseIgnorableSpans is the Unicode Case_Ignorable property, which Final_Sigma skips over."),
    ):
        lines.append("// " + comment)
        lines.append("var %s = [][2]rune{" % name)
        for lo, hi in document[key]:
            lines.append("\t{0x%04X, 0x%04X}," % (lo, hi))
        lines.append("}\n")
    lines.append("// referenceLowerSpan maps a run of runes to the rune at a fixed offset.")
    lines.append("type referenceLowerSpan struct{ lo, hi, delta rune }\n")
    lines.append("var referenceLowerSpans = []referenceLowerSpan{")
    for lo, hi, delta in spans:
        lines.append("\t{0x%04X, 0x%04X, %d}," % (lo, hi, delta))
    lines.append("}\n")
    lines.append("// referenceLowerExpansions holds the mappings that produce several runes.")
    lines.append("var referenceLowerExpansions = map[rune]string{")
    for point, parts in sorted(expansions.items()):
        lines.append('\t0x%04X: "%s",' % (point, "".join("\\u%04x" % c for c in parts)))
    lines.append("}")
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(lines) + "\n")
    return len(spans), len(expansions)


def main():
    whitespace, cased, ignorable, lower = [], [], [], {}
    for point in range(0x110000):
        if 0xD800 <= point <= 0xDFFF:
            continue
        character = chr(point)
        if character.isspace():
            whitespace.append(point)
        folded = character.lower()
        if folded != character:
            lower["%04X" % point] = " ".join("%04X" % ord(c) for c in folded)
        if character.isupper() or character.islower() or unicodedata.category(character) == "Lt":
            cased.append(point)
            continue
        if ("ΑΣ" + character + "Α").lower()[1] == "σ":
            ignorable.append(point)
    document = {
        "unicode_version": unicodedata.unidata_version,
        "whitespace": whitespace,
        "cased": ranges(cased),
        "case_ignorable": ranges(ignorable),
        "lower": lower,
        "probes": [{"input": text, "lower": text.lower()} for text in PROBES],
    }
    path = os.path.join(HERE, "unicode_vectors.json")
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(document, handle, indent=2)
        handle.write("\n")
    spans, expansions = write_go(document, os.path.join(os.path.dirname(HERE), "unicode_tables.go"))
    print("wrote %d whitespace, %d cased ranges, %d ignorable ranges, %d lower mappings, %d probes to %s"
          % (len(whitespace), len(document["cased"]), len(document["case_ignorable"]),
             len(lower), len(PROBES), path))
    print("wrote unicode_tables.go: %d lower spans, %d expansions" % (spans, expansions))


if __name__ == "__main__":
    main()